const getTypeBadgeVariant = (baseType: string): string => {
  const variantMap: Record<string, string> = {
    'string': 'info',
    'int': 'success',
    'bigint': 'warning',
    'float': 'primary',
    'boolean': 'danger',
    'datetime': 'info',
    'array': 'primary',
    'map': 'secondary'
  };
  return variantMap[baseType] || 'secondary';
};

function ParametersList() {
  // ⚡️ Performance monitoring
