  return (
    <div className="games-container">
      <h2>Games (GraphQL)</h2>
      <table>
        <thead>
          <tr>
            <th>GID</th>
            <th>Name</th>
            <th>ODS DB</th>
            <th>Events</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {games.map((game: any) => (
            <tr key={game.gid}>
              <td>{game.gid}</td>
              <td>{game.name}</td>
              <td>{game.odsDb}</td>
              <td>{game.eventCount}</td>
              <td>
                <button onClick={() => handleDelete(game.gid, true)}>
                  Delete
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default GamesGraphQL;

