/**
 * Form Component - Main Test Suite
 * 
 * Comprehensive tests for Form component including:
 * - Rendering behavior
 * - Form submission
 * - Validation
 * - Error handling
 * - Context management
 */

import { zodResolver } from '@hookform/resolvers/zod';
import { render, screen, waitFor } from '@test/test-utils';
import userEvent from '@testing-library/user-event';
import React from 'react';
import { useForm } from 'react-hook-form';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { z } from 'zod';

import Form, { useFormContextValue } from './Form';

import { FormInput, FormSelect, FormCheckbox, FormRadio } from './index';

// Test schema
const testSchema = z.object({
  email: z.string().email('Invalid email'),
  password: z.string().min(8, 'Password must be at least 8 characters'),
  agree: z.boolean().refine(val => val === true, 'You must agree to terms'),
  sport: z.string().min(1, 'Please select a sport'),
});

type TestFormData = z.infer<typeof testSchema>;

// Test wrapper component
const TestFormWrapper = ({
  children,
  schema = testSchema,
  mode = 'onTouched',
  defaultValues = { email: '', password: '', agree: false, sport: '' },
}: {
  children: React.ReactNode;
  schema?: any;
  mode?: any;
  defaultValues?: any;
}) => {
  const form = useForm<TestFormData>({
    resolver: zodResolver(schema),
    mode,
    defaultValues,
  });

  return (
    <Form form={form} onSubmit={vi.fn()}>
      {children}
    </Form>
  );
};

describe('Form Component', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  describe('rendering', () => {
    it('should render form element with role', () => {
      render(<TestFormWrapper><div>Test</div></TestFormWrapper>);
      expect(screen.getByRole('form')).toBeInTheDocument();
    });

    it('should render children components', () => {
      render(
        <TestFormWrapper>
          <div>Child 1</div>
          <div>Child 2</div>
        </TestFormWrapper>
      );
      expect(screen.getByText('Child 1')).toBeInTheDocument();
      expect(screen.getByText('Child 2')).toBeInTheDocument();
    });

    it('should have noValidate attribute', () => {
      render(<TestFormWrapper><div>Test</div></TestFormWrapper>);
      const form = screen.getByRole('form');
      expect(form).toHaveAttribute('noValidate');
    });

    it('should apply custom className', () => {
      const form = useForm();
      render(
        <Form form={form} onSubmit={() => {}} className="custom-class">
          <div>Test</div>
        </Form>
      );
      const formElement = screen.getByRole('form');
      expect(formElement).toHaveClass('custom-class');
    });

    it('should apply custom id', () => {
      const form = useForm();
      render(
        <Form form={form} onSubmit={() => {}} id="test-form">
          <div>Test</div>
        </Form>
      );
      const formElement = screen.getByRole('form');
      expect(formElement).toHaveAttribute('id', 'test-form');
    });
  });

  describe('interactions', () => {
    it('should call onSubmit with valid data', async () => {
      const user = userEvent.setup();
      const handleSubmit = vi.fn();

      const TestForm = () => {
        const form = useForm({
          resolver: zodResolver(testSchema),
          defaultValues: { email: '', password: '', agree: false, sport: '' },
        });

        return (
          <Form form={form} onSubmit={handleSubmit}>
            <FormInput name="email" label="Email" type="email" />
            <FormInput name="password" label="Password" type="password" />
            <FormCheckbox name="agree" label="I agree" />
            <FormRadio 
              name="sport" 
              label="Sport"
              options={[
                { value: 'football', label: 'Football' },
                { value: 'basketball', label: 'Basketball' }
              ]}
            />
            <button type="submit">Submit</button>
          </Form>
        );
      };

      render(<TestForm />);

      await user.type(screen.getByLabelText(/email/i), 'test@example.com');
      await user.type(screen.getByLabelText(/password/i), 'password123');
      await user.click(screen.getByLabelText(/i agree/i));
      await user.click(screen.getByLabelText(/football/i));
      await user.click(screen.getByRole('button', { name: /submit/i }));

      await waitFor(() => {
        expect(handleSubmit).toHaveBeenCalledTimes(1);
        expect(handleSubmit).toHaveBeenCalledWith({
          email: 'test@example.com',
          password: 'password123',
          agree: true,
          sport: 'football',
        });
      });
    });

    it('should not call onSubmit with invalid data', async () => {
      const user = userEvent.setup();
      const handleSubmit = vi.fn();

      const TestForm = () => {
        const form = useForm({
          resolver: zodResolver(testSchema),
          defaultValues: { email: '', password: '', agree: false, sport: '' },
        });

        return (
          <Form form={form} onSubmit={handleSubmit}>
            <FormInput name="email" label="Email" type="email" />
            <FormInput name="password" label="Password" type="password" />
            <FormCheckbox name="agree" label="I agree" />
            <button type="submit">Submit</button>
          </Form>
        );
      };

      render(<TestForm />);

      await user.click(screen.getByRole('button', { name: /submit/i }));

      await waitFor(() => {
        expect(handleSubmit).not.toHaveBeenCalled();
      });
    });

    it('should prevent default form submission', async () => {
      const user = userEvent.setup();
      const handleSubmit = vi.fn();

      const TestForm = () => {
        const form = useForm({
          resolver: zodResolver(testSchema),
          defaultValues: { email: 'test@example.com', password: 'password123', agree: true, sport: 'football' },
        });

        return (
          <Form form={form} onSubmit={handleSubmit}>
            <button type="submit">Submit</button>
          </Form>
        );
      };

      render(<TestForm />);

      await user.click(screen.getByRole('button', { name: /submit/i }));

      await waitFor(() => {
        expect(handleSubmit).toHaveBeenCalledTimes(1);
      });
    });
  });

  describe('edge cases', () => {
    it('should handle empty children', () => {
      const form = useForm();
      render(<Form form={form} onSubmit={() => {}} />);
      expect(screen.getByRole('form')).toBeInTheDocument();
    });

    it('should handle resetAfterSubmit option', async () => {
      const user = userEvent.setup();
      const handleSubmit = vi.fn();

      const TestForm = () => {
        const form = useForm({
          defaultValues: { email: '', password: '', agree: false, sport: '' },
        });

        return (
          <Form form={form} onSubmit={handleSubmit} resetAfterSubmit>
            <FormInput name="email" label="Email" />
            <button type="submit">Submit</button>
          </Form>
        );
      };

      render(<TestForm />);

      const emailInput = screen.getByLabelText(/email/i);
      await user.type(emailInput, 'test@example.com');
      expect(emailInput).toHaveValue('test@example.com');

      await user.click(screen.getByRole('button', { name: /submit/i }));

      await waitFor(() => {
        expect(emailInput).toHaveValue('');
      });
    });

    it('should handle async onSubmit', async () => {
      const user = userEvent.setup();
      const handleSubmit = vi.fn(async () => {
        await new Promise(resolve => setTimeout(resolve, 100));
      });

      const TestForm = () => {
        const form = useForm({
          defaultValues: { email: 'test@example.com', password: 'password123', agree: true, sport: 'football' },
        });

        return (
          <Form form={form} onSubmit={handleSubmit}>
            <button type="submit">Submit</button>
          </Form>
        );
      };

      render(<TestForm />);

      await user.click(screen.getByRole('button', { name: /submit/i }));

      await waitFor(() => {
        expect(handleSubmit).toHaveBeenCalledTimes(1);
      }, { timeout: 1000 });
    });

    it('should handle form with only optional fields', async () => {
      const user = userEvent.setup();
      const handleSubmit = vi.fn();

      const optionalSchema = z.object({
        name: z.string().optional(),
      });

      const TestForm = () => {
        const form = useForm({
          resolver: zodResolver(optionalSchema),
          defaultValues: { name: '' },
        });

        return (
          <Form form={form} onSubmit={handleSubmit}>
            <FormInput name="name" label="Name" />
            <button type="submit">Submit</button>
          </Form>
        );
      };

      render(<TestForm />);

      await user.click(screen.getByRole('button', { name: /submit/i }));

      await waitFor(() => {
        expect(handleSubmit).toHaveBeenCalledWith({ name: '' });
      });
    });
  });

  describe('error handling', () => {
    it('should display validation errors', async () => {
      const user = userEvent.setup();

      const TestForm = () => {
        const form = useForm({
          resolver: zodResolver(testSchema),
          defaultValues: { email: '', password: '', agree: false, sport: '' },
        });

        return (
          <Form form={form} onSubmit={() => {}}>
            <FormInput name="email" label="Email" type="email" />
            <FormInput name="password" label="Password" type="password" />
            <FormCheckbox name="agree" label="I agree" required />
            <button type="submit">Submit</button>
          </Form>
        );
      };

      render(<TestForm />);

      await user.click(screen.getByRole('button', { name: /submit/i }));

      await waitFor(() => {
        expect(screen.getByText(/invalid email/i)).toBeInTheDocument();
        expect(screen.getByText(/password must be at least 8 characters/i)).toBeInTheDocument();
        expect(screen.getByText(/you must agree to terms/i)).toBeInTheDocument();
      });
    });

    it('should clear errors when valid input is provided', async () => {
      const user = userEvent.setup();

      const TestForm = () => {
        const form = useForm({
          resolver: zodResolver(testSchema),
          defaultValues: { email: '', password: '', agree: false, sport: '' },
        });

        return (
          <Form form={form} onSubmit={() => {}}>
            <FormInput name="email" label="Email" type="email" />
            <button type="submit">Submit</button>
          </Form>
        );
      };

      render(<TestForm />);

      await user.click(screen.getByRole('button', { name: /submit/i }));

      await waitFor(() => {
        expect(screen.getByText(/invalid email/i)).toBeInTheDocument();
      });

      const emailInput = screen.getByLabelText(/email/i);
      await user.type(emailInput, 'test@example.com');

      await waitFor(() => {
        expect(screen.queryByText(/invalid email/i)).not.toBeInTheDocument();
      });
    });

    it('should handle submission errors gracefully', async () => {
      const user = userEvent.setup();
      const handleSubmit = vi.fn(() => {
        throw new Error('Submission failed');
      });

      const TestForm = () => {
        const form = useForm({
          defaultValues: { email: 'test@example.com', password: 'password123', agree: true, sport: 'football' },
        });

        return (
          <Form form={form} onSubmit={handleSubmit}>
            <button type="submit">Submit</button>
          </Form>
        );
      };

      render(<TestForm />);

      await user.click(screen.getByRole('button', { name: /submit/i }));

      await waitFor(() => {
        expect(handleSubmit).toHaveBeenCalled();
      });
    });
  });

  describe('context management', () => {
    it('should provide form context to children', () => {
      let contextValue: any;

      const TestChild = () => {
        contextValue = useFormContextValue();
        return <div>Test</div>;
      };

      const form = useForm();

      render(
        <Form form={form} onSubmit={() => {}}>
          <TestChild />
        </Form>
      );

      expect(contextValue).toBeDefined();
      expect(contextValue.form).toBe(form);
      expect(contextValue.isSubmitting).toBe(false);
      expect(contextValue.isValid).toBe(true);
      expect(contextValue.isDirty).toBe(false);
    });

    it('should update context when form state changes', async () => {
      const user = userEvent.setup();
      let contextValue: any;

      const TestChild = () => {
        contextValue = useFormContextValue();
        return <div>Test</div>;
      };

      const TestForm = () => {
        const form = useForm({
          defaultValues: { email: '' },
        });

        return (
          <Form form={form} onSubmit={() => {}}>
            <FormInput name="email" label="Email" />
            <TestChild />
          </Form>
        );
      };

      render(<TestForm />);

      expect(contextValue.isDirty).toBe(false);

      await user.type(screen.getByLabelText(/email/i), 'test');

      expect(contextValue.isDirty).toBe(true);
    });

    it('should throw error when useFormContextValue is used outside Form', () => {
      const TestChild = () => {
        expect(() => useFormContextValue()).toThrow('useFormContextValue must be used within a Form component');
        return <div>Test</div>;
      };

      render(<TestChild />);
    });
  });
});

import { UseFormReturn, FieldValues, FieldPath } from 'react-hook-form';
import { z } from 'zod';

/**
 * Form validation mode options
 */
export type FormValidationMode = 'onBlur' | 'onChange' | 'onSubmit' | 'onTouched' | 'all';

/**
 * Form submission state
 */
export interface FormSubmissionState {
  isSubmitting: boolean;
  isValid: boolean;
  isDirty: boolean;
  submitCount: number;
}

/**
 * Common field props for all form fields
 */
export interface FormFieldProps<TFieldValues extends FieldValues = FieldValues> {
  /**
   * Field name - must match a key in the form schema
   */
  name: FieldPath<TFieldValues>;

  /**
   * Field label
   */
  label?: string;

  /**
   * Helper text displayed below the field
   */
  helperText?: string;

  /**
   * Whether the field is required
   */
  required?: boolean;

  /**
   * Whether the field is disabled
   */
  disabled?: boolean;

  /**
   * Additional CSS class names
   */
  className?: string;
}

/**
 * Form component props
 */
export interface FormProps<TFieldValues extends FieldValues = FieldValues, TContext = any> {
  /**
   * React Hook Form instance
   */
  form: UseFormReturn<TFieldValues, TContext>;

  /**
   * Form submission handler
   */
  onSubmit: (data: TFieldValues) => void | Promise<void>;

  /**
   * Validation mode
   * @default 'onBlur'
   */
  validationMode?: FormValidationMode;

  /**
   * Re-validate mode when data changes
   * @default 'onChange'
   */
  reValidateMode?: FormValidationMode;

  /**
   * Children components
   */
  children: React.ReactNode;

  /**
   * Additional CSS class names
   */
  className?: string;

  /**
   * Form ID
   */
  id?: string;

  /**
   * Whether to reset form after successful submission
   * @default false
   */
  resetAfterSubmit?: boolean;
}

/**
 * Form context type
 */
export interface FormContextValue<TFieldValues extends FieldValues = FieldValues, TContext = any> {
  form: UseFormReturn<TFieldValues, TContext>;
  isSubmitting: boolean;
  isValid: boolean;
  isDirty: boolean;
}

/**
 * Input field specific props
 */
export interface InputFieldProps<TFieldValues extends FieldValues = FieldValues>
  extends FormFieldProps<TFieldValues> {
  /**
   * Input type
   * @default 'text'
   */
  type?: 'text' | 'email' | 'password' | 'number' | 'tel' | 'url' | 'search';

  /**
   * Placeholder text
   */
  placeholder?: string;

  /**
   * Auto-complete attribute
   */
  autoComplete?: string;
}

/**
 * Select option
 */
export interface SelectOption {
  value: string | number;
  label: string;
  disabled?: boolean;
}

/**
 * Select field specific props
 */
export interface SelectFieldProps<TFieldValues extends FieldValues = FieldValues>
  extends FormFieldProps<TFieldValues> {
  /**
   * Available options
   */
  options: SelectOption[];

  /**
   * Placeholder text
   */
  placeholder?: string;

  /**
   * Enable search functionality
   */
  searchable?: boolean;
}

/**
 * Checkbox field specific props
 */
export interface CheckboxFieldProps<TFieldValues extends FieldValues = FieldValues>
  extends Omit<FormFieldProps<TFieldValues>, 'label'> {
  /**
   * Checkbox label
   */
  label?: string;

  /**
   * Indeterminate state
   */
  indeterminate?: boolean;
}

/**
 * Radio option
 */
export interface RadioOption {
  value: string;
  label: string;
  disabled?: boolean;
}

/**
 * Radio field specific props
 */
export interface RadioFieldProps<TFieldValues extends FieldValues = FieldValues>
  extends FormFieldProps<TFieldValues> {
  /**
   * Available options
   */
  options: RadioOption[];

  /**
   * Layout direction
   * @default 'column'
   */
  direction?: 'row' | 'column';
}

/**
 * Form error message component props
 */
export interface FormErrorMessageProps {
  /**
   * Error message to display
   */
  error?: string;

  /**
   * Additional CSS class names
   */
  className?: string;
}

/**
 * Form helper text component props
 */
export interface FormHelperTextProps {
  /**
   * Helper text to display
   */
  text?: string;

  /**
   * Additional CSS class names
   */
  className?: string;
}

/**
 * Date picker field specific props
 */
export interface DatePickerFieldProps<TFieldValues extends FieldValues = FieldValues>
  extends FormFieldProps<TFieldValues> {
  /**
   * Date format
   * @default 'YYYY-MM-DD'
   */
  format?: string;

  /**
   * Show time picker
   * @default false
   */
  showTime?: boolean;

  /**
   * Time format
   * @default 'HH:mm'
   */
  timeFormat?: string;

  /**
   * Minimum date
   */
  minDate?: Date;

  /**
   * Maximum date
   */
  maxDate?: Date;

  /**
   * Placeholder text
   */
  placeholder?: string;
}

/**
 * Upload file item
 */
export interface UploadFile {
  /**
   * File unique identifier
   */
  id: string;

  /**
   * Original file
   */
  file: File;

  /**
   * Upload progress (0-100)
   */
  progress?: number;

  /**
   * Upload status
   */
  status?: 'pending' | 'uploading' | 'success' | 'error';

  /**
   * Error message if upload failed
   */
  error?: string;

  /**
   * Preview URL for images
   */
  previewUrl?: string;
}

/**
 * Upload field specific props
 */
export interface UploadFieldProps<TFieldValues extends FieldValues = FieldValues>
  extends FormFieldProps<TFieldValues> {
  /**
   * Accepted file types
   * @example 'image/*,.pdf'
   */
  accept?: string;

  /**
   * Allow multiple files
   * @default false
   */
  multiple?: boolean;

  /**
   * Maximum file size in bytes
   * @default 5242880 (5MB)
   */
  maxSize?: number;

  /**
   * Maximum number of files
   * @default 10
   */
  maxFiles?: number;

  /**
   * Enable drag and drop
   * @default true
   */
  enableDragDrop?: boolean;

  /**
   * Upload handler
   */
  onUpload?: (files: File[]) => Promise<UploadFile[]>;

  /**
   * Custom upload button text
   */
  buttonText?: string;

  /**
   * Show file preview
   * @default true
   */
  showPreview?: boolean;
}

/**
 * Rich text field specific props
 */
export interface RichTextFieldProps<TFieldValues extends FieldValues = FieldValues>
  extends FormFieldProps<TFieldValues> {
  /**
   * Maximum character length
   */
  maxLength?: number;

  /**
   * Show character count
   * @default true
   */
  showCharCount?: boolean;

  /**
   * Toolbar configuration
   * @default ['bold', 'italic', 'underline', 'link', 'list']
   */
  toolbar?: ('bold' | 'italic' | 'underline' | 'link' | 'list' | 'heading')[];

  /**
   * Placeholder text
   */
  placeholder?: string;

  /**
   * Minimum height in pixels
   * @default 150
   */
  minHeight?: number;

  /**
   * Maximum height in pixels
   * @default 400
   */
  maxHeight?: number;
}

