/**
 * Form Component Tests
 * 
 * Tests for the Form component that integrates React Hook Form with validation.
 */

import { zodResolver } from '@hookform/resolvers/zod';
import { render, screen, fireEvent, waitFor } from '@test/test-utils';
import userEvent from '@testing-library/user-event';
import React from 'react';
import { useForm } from 'react-hook-form';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { z } from 'zod';

import Form, { FormErrorMessage, FormHelperText, useFormContextValue } from '../Form';

// Test schema
const testSchema = z.object({
  email: z.string().email('Invalid email'),
  password: z.string().min(8, 'Password must be at least 8 characters'),
});

type TestFormData = z.infer<typeof testSchema>;

// Test wrapper component
const TestForm = ({
  onSubmit,
  defaultValues,
}: {
  onSubmit: (data: TestFormData) => void;
  defaultValues?: Partial<TestFormData>;
}) => {
  const form = useForm<TestFormData>({
    resolver: zodResolver(testSchema),
    defaultValues: {
      email: defaultValues?.email || '',
      password: defaultValues?.password || '',
    },
  });

  return (
    <Form form={form} onSubmit={onSubmit}>
      <div>
        <label htmlFor="email">Email</label>
        <input
          id="email"
          type="email"
          {...form.register('email')}
          placeholder="Enter email"
        />
        {form.formState.errors.email && (
          <FormErrorMessage error={form.formState.errors.email.message} />
        )}
      </div>
      <div>
        <label htmlFor="password">Password</label>
        <input
          id="password"
          type="password"
          {...form.register('password')}
          placeholder="Enter password"
        />
        {form.formState.errors.password && (
          <FormErrorMessage error={form.formState.errors.password.message} />
        )}
      </div>
      <button type="submit" disabled={form.formState.isSubmitting}>
        Submit
      </button>
    </Form>
  );
};

describe('Form Component', () => {
  const mockSubmit = vi.fn();

  beforeEach(() => {
    vi.clearAllMocks();
  });

  describe('Rendering', () => {
    it('should render form element', () => {
      render(<TestForm onSubmit={mockSubmit} />);

      expect(screen.getByRole('form')).toBeInTheDocument();
    });

    it('should render children', () => {
      render(<TestForm onSubmit={mockSubmit} />);

      expect(screen.getByLabelText(/email/i)).toBeInTheDocument();
      expect(screen.getByLabelText(/password/i)).toBeInTheDocument();
      expect(screen.getByRole('button', { name: /submit/i })).toBeInTheDocument();
    });

    it('should have noValidate attribute', () => {
      render(<TestForm onSubmit={mockSubmit} />);

      const form = screen.getByRole('form');
      expect(form).toHaveAttribute('noValidate');
    });

    it('should apply custom className', () => {
      const TestFormWithClassName = () => {
        const form = useForm();
        return (
          <Form form={form} onSubmit={() => {}} className="custom-class">
            <div>Test</div>
          </Form>
        );
      };

      render(<TestFormWithClassName />);

      const formElement = screen.getByRole('form');
      expect(formElement).toHaveClass('custom-class');
    });

    it('should apply custom id', () => {
      const TestFormWithId = () => {
        const form = useForm();
        return (
          <Form form={form} onSubmit={() => {}} id="test-form">
            <div>Test</div>
          </Form>
        );
      };

      render(<TestFormWithId />);

      const formElement = screen.getByRole('form');
      expect(formElement).toHaveAttribute('id', 'test-form');
    });
  });

  describe('Form Submission', () => {
    it('should call onSubmit with form data when valid', async () => {
      const user = userEvent.setup();
      render(<TestForm onSubmit={mockSubmit} />);

      await user.type(screen.getByLabelText(/email/i), 'test@example.com');
      await user.type(screen.getByLabelText(/password/i), 'password123');
      await user.click(screen.getByRole('button', { name: /submit/i }));

      await waitFor(() => {
        expect(mockSubmit).toHaveBeenCalledWith({
          email: 'test@example.com',
          password: 'password123',
        });
      });
    });

    it('should not call onSubmit when form is invalid', async () => {
      const user = userEvent.setup();
      render(<TestForm onSubmit={mockSubmit} />);

      await user.type(screen.getByLabelText(/email/i), 'invalid-email');
      await user.type(screen.getByLabelText(/password/i), 'short');
      await user.click(screen.getByRole('button', { name: /submit/i }));

      await waitFor(() => {
        expect(mockSubmit).not.toHaveBeenCalled();
      });
    });

    it('should show validation errors on submit', async () => {
      const user = userEvent.setup();
      render(<TestForm onSubmit={mockSubmit} />);

      await user.click(screen.getByRole('button', { name: /submit/i }));

      await waitFor(() => {
        expect(screen.getByText(/invalid email/i)).toBeInTheDocument();
      });
    });

    it('should prevent default form submission', async () => {
      const user = userEvent.setup();
      const preventDefaultMock = vi.fn();

      render(<TestForm onSubmit={mockSubmit} />);

      const form = screen.getByRole('form');
      const submitEvent = new Event('submit', {
        bubbles: true,
        cancelable: true,
      });
      Object.defineProperty(submitEvent, 'preventDefault', {
        value: preventDefaultMock,
      });

      fireEvent(form, submitEvent);

      expect(preventDefaultMock).toHaveBeenCalled();
    });
  });

  describe('Reset After Submit', () => {
    it('should reset form when resetAfterSubmit is true', async () => {
      const user = userEvent.setup();

      const TestFormWithReset = () => {
        const form = useForm<TestFormData>({
          defaultValues: { email: '', password: '' },
        });

        return (
          <Form form={form} onSubmit={mockSubmit} resetAfterSubmit>
            <input {...form.register('email')} placeholder="email" />
            <input {...form.register('password')} placeholder="password" />
            <button type="submit">Submit</button>
          </Form>
        );
      };

      render(<TestFormWithReset />);

      await user.type(screen.getByPlaceholderText('email'), 'test@example.com');
      await user.type(screen.getByPlaceholderText('password'), 'password123');
      await user.click(screen.getByRole('button', { name: /submit/i }));

      await waitFor(() => {
        expect(screen.getByPlaceholderText('email')).toHaveValue('');
        expect(screen.getByPlaceholderText('password')).toHaveValue('');
      });
    });

    it('should not reset form when resetAfterSubmit is false', async () => {
      const user = userEvent.setup();

      const TestFormWithoutReset = () => {
        const form = useForm<TestFormData>({
          defaultValues: { email: '', password: '' },
        });

        return (
          <Form form={form} onSubmit={mockSubmit} resetAfterSubmit={false}>
            <input {...form.register('email')} placeholder="email" />
            <input {...form.register('password')} placeholder="password" />
            <button type="submit">Submit</button>
          </Form>
        );
      };

      render(<TestFormWithoutReset />);

      await user.type(screen.getByPlaceholderText('email'), 'test@example.com');
      await user.type(screen.getByPlaceholderText('password'), 'password123');
      await user.click(screen.getByRole('button', { name: /submit/i }));

      await waitFor(() => {
        expect(mockSubmit).toHaveBeenCalled();
      });

      // Form should retain values
      expect(screen.getByPlaceholderText('email')).toHaveValue('test@example.com');
      expect(screen.getByPlaceholderText('password')).toHaveValue('password123');
    });
  });

  describe('Form State', () => {
    it('should track isSubmitting state', async () => {
      let isSubmittingState = false;

      const TestFormWithState = () => {
        const form = useForm();
        isSubmittingState = form.formState.isSubmitting;

        return (
          <Form form={form} onSubmit={async () => {}}>
            <button type="submit">Submit</button>
          </Form>
        );
      };

      render(<TestFormWithState />);

      expect(isSubmittingState).toBe(false);
    });

    it('should track isValid state', () => {
      const TestFormWithValidState = () => {
        const form = useForm<TestFormData>({
          resolver: zodResolver(testSchema),
          defaultValues: { email: '', password: '' },
        });

        return (
          <Form form={form} onSubmit={() => {}}>
            <div data-testid="valid-state">{form.formState.isValid ? 'Valid' : 'Invalid'}</div>
          </Form>
        );
      };

      render(<TestFormWithValidState />);

      expect(screen.getByTestId('valid-state')).toHaveTextContent('Invalid');
    });

    it('should track isDirty state', async () => {
      const user = userEvent.setup();

      const TestFormWithDirtyState = () => {
        const form = useForm<TestFormData>({
          defaultValues: { email: '', password: '' },
        });

        return (
          <Form form={form} onSubmit={() => {}}>
            <input {...form.register('email')} placeholder="email" />
            <div data-testid="dirty-state">{form.formState.isDirty ? 'Dirty' : 'Clean'}</div>
          </Form>
        );
      };

      render(<TestFormWithDirtyState />);

      expect(screen.getByTestId('dirty-state')).toHaveTextContent('Clean');

      await user.type(screen.getByPlaceholderText('email'), 'test@example.com');

      await waitFor(() => {
        expect(screen.getByTestId('dirty-state')).toHaveTextContent('Dirty');
      });
    });
  });
});

describe('FormErrorMessage', () => {
  it('should render error message', () => {
    render(<FormErrorMessage error="Test error message" />);

    expect(screen.getByText('Test error message')).toBeInTheDocument();
  });

  it('should not render when error is null', () => {
    render(<FormErrorMessage error={null} />);

    expect(screen.queryByRole('alert')).not.toBeInTheDocument();
  });

  it('should not render when error is undefined', () => {
    render(<FormErrorMessage error={undefined} />);

    expect(screen.queryByRole('alert')).not.toBeInTheDocument();
  });

  it('should have alert role', () => {
    render(<FormErrorMessage error="Test error" />);

    expect(screen.getByRole('alert')).toBeInTheDocument();
  });

  it('should have aria-live attribute', () => {
    render(<FormErrorMessage error="Test error" />);

    const alert = screen.getByRole('alert');
    expect(alert).toHaveAttribute('aria-live', 'polite');
  });

  it('should apply custom className', () => {
    render(<FormErrorMessage error="Test error" className="custom-error" />);

    const error = screen.getByRole('alert');
    expect(error).toHaveClass('custom-error');
  });
});

describe('FormHelperText', () => {
  it('should render helper text', () => {
    render(<FormHelperText text="Helper text" />);

    expect(screen.getByText('Helper text')).toBeInTheDocument();
  });

  it('should not render when text is null', () => {
    render(<FormHelperText text={null} />);

    expect(screen.queryByText('Helper text')).not.toBeInTheDocument();
  });

  it('should not render when text is undefined', () => {
    render(<FormHelperText text={undefined} />);

    expect(screen.queryByText('Helper text')).not.toBeInTheDocument();
  });

  it('should not render when text is empty string', () => {
    render(<FormHelperText text="" />);

    expect(screen.queryByText('Helper text')).not.toBeInTheDocument();
  });

  it('should apply custom className', () => {
    render(<FormHelperText text="Helper text" className="custom-helper" />);

    const helper = screen.getByText('Helper text');
    expect(helper).toHaveClass('custom-helper');
  });
});

describe('useFormContextValue Hook', () => {
  it('should throw error when used outside Form component', () => {
    const TestChild = () => {
      expect(() => useFormContextValue()).toThrow('useFormContextValue must be used within a Form component');
      return <div>Test</div>;
    };

    render(<TestChild />);
  });

  it('should provide form context value when used within Form component', () => {
    let contextValue: any;

    const TestChild = () => {
      contextValue = useFormContextValue();
      return <div>Test</div>;
    };

    const TestFormWithContext = () => {
      const form = useForm();

      return (
        <Form form={form} onSubmit={() => {}}>
          <TestChild />
        </Form>
      );
    };

    render(<TestFormWithContext />);

    expect(contextValue).toBeDefined();
    expect(contextValue.form).toBeDefined();
    expect(contextValue.isSubmitting).toBe(false);
    expect(contextValue.isDirty).toBe(false);
  });
});

/**
 * Modal Component Unit Tests
 * 
 * Comprehensive test suite for Modal component
 * Target coverage: 90%
 * 
 * Test Categories:
 * 1. Rendering Tests
 * 2. Interaction Tests
 * 3. Accessibility Tests
 * 4. Lifecycle Tests
 * 5. Edge Cases
 * 6. Performance Tests
 */

import { render, screen, fireEvent, waitFor } from '@test/test-utils';
import userEvent from '@testing-library/user-event';
import React from 'react';
import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';

import Modal from './Modal';

// Mock constants
vi.mock('@shared/constants/timeouts', () => ({
  MODAL_ANIMATION_DELAY: 100,
}));

vi.mock('@shared/constants/zIndices', () => ({
  Z_INDICES: {
    MODAL: 1000,
  },
}));

describe('Modal Component', () => {
  const defaultProps = {
    isOpen: false,
    onClose: vi.fn(),
    title: 'Test Modal',
    children: <div>Modal Content</div>,
  };

  beforeEach(() => {
    // Reset document body styles before each test
    document.body.style.overflow = '';
    document.body.style.paddingRight = '';
    vi.clearAllMocks();
  });

  afterEach(() => {
    // Cleanup after each test
    document.body.style.overflow = '';
    document.body.style.paddingRight = '';
  });

  // ========== Rendering Tests ==========

  describe('Rendering', () => {
    it('should not render when isOpen is false', () => {
      render(<Modal {...defaultProps} isOpen={false} />);

      expect(screen.queryByRole('dialog')).not.toBeInTheDocument();
      expect(screen.queryByRole('dialog', { hidden: true })).not.toBeInTheDocument();
    });

    it('should render when isOpen is true', () => {
      render(<Modal {...defaultProps} isOpen={true} />);

      expect(screen.getByRole('dialog')).toBeInTheDocument();
      expect(screen.getByText('Test Modal')).toBeInTheDocument();
      expect(screen.getByText('Modal Content')).toBeInTheDocument();
    });

    it('should render with custom title', () => {
      render(<Modal {...defaultProps} isOpen={true} title="Custom Title" />);

      expect(screen.getByText('Custom Title')).toBeInTheDocument();
    });

    it('should render with custom className', () => {
      render(<Modal {...defaultProps} isOpen={true} className="custom-class" />);

      const modal = screen.getByRole('dialog');
      expect(modal).toHaveClass('custom-class');
    });

    it('should render with custom style', () => {
      const customStyle = { backgroundColor: 'red' };
      render(<Modal {...defaultProps} isOpen={true} style={customStyle} />);

      const modal = screen.getByRole('dialog');
      // Check that style is applied (may have transform from draggable)
      expect(modal.style.backgroundColor).toBe('red');
    });

    it('should render with custom zIndex', () => {
      render(<Modal {...defaultProps} isOpen={true} zIndex={9999} />);

      const overlay = screen.getByRole('dialog').parentElement;
      expect(overlay).toHaveStyle({ zIndex: '9999' });
    });

    it('should render footer when showFooter is true', () => {
      render(
        <Modal 
          {...defaultProps} 
          isOpen={true} 
          showFooter={true} 
          footer={<div>Footer Content</div>}
        />
      );

      expect(screen.getByText('Footer Content')).toBeInTheDocument();
    });

    it('should not render header when showHeader is false', () => {
      render(<Modal {...defaultProps} isOpen={true} showHeader={false} />);

      expect(screen.queryByText('Test Modal')).not.toBeInTheDocument();
    });

    it('should not render close button when showCloseButton is false', () => {
      render(<Modal {...defaultProps} isOpen={true} showCloseButton={false} />);

      expect(screen.queryByLabelText('关闭对话框')).not.toBeInTheDocument();
    });

    it('should render all size variants', () => {
      const sizes: Array<'sm' | 'md' | 'lg' | 'xl' | 'full'> = ['sm', 'md', 'lg', 'xl', 'full'];

      sizes.forEach((size) => {
        const { unmount } = render(<Modal {...defaultProps} isOpen={true} size={size} />);
        const modal = screen.getByRole('dialog');
        expect(modal).toHaveClass(`modal-content--${size}`);
        unmount();
      });
    });

    it('should render fullScreen mode correctly', () => {
      render(<Modal {...defaultProps} isOpen={true} fullScreen={true} />);

      const modal = screen.getByRole('dialog');
      expect(modal).toHaveClass('modal-content--full');
    });

    it('should render all animation variants', () => {
      const animations: Array<'slideUp' | 'fadeIn' | 'scale' | 'none'> = ['slideUp', 'fadeIn', 'scale', 'none'];

      animations.forEach((animation) => {
        const { unmount } = render(<Modal {...defaultProps} isOpen={true} animation={animation} />);
        const overlay = screen.getByTestId('modal-overlay');
        // 'none' animation doesn't add a class
        if (animation === 'none') {
          expect(overlay).not.toHaveClass('modal-overlay--none');
        } else {
          expect(overlay).toHaveClass(`modal-overlay--${animation}`);
        }
        unmount();
      });
    });

    it('should render glassmorphism effect', () => {
      render(<Modal {...defaultProps} isOpen={true} glassmorphism={true} />);

      const modal = screen.getByRole('dialog');
      expect(modal).toHaveClass('modal-content--glassmorphism');
    });

    it('should render all variant types', () => {
      const variants: Array<'default' | 'danger' | 'warning' | 'success' | 'info'> = 
        ['default', 'danger', 'warning', 'success', 'info'];

      variants.forEach((variant) => {
        const { unmount } = render(<Modal {...defaultProps} isOpen={true} variant={variant} />);
        const modal = screen.getByRole('dialog');
        // 'default' variant doesn't add a class
        if (variant === 'default') {
          expect(modal).not.toHaveClass('modal-content--default');
        } else {
          expect(modal).toHaveClass(`modal-content--${variant}`);
        }
        unmount();
      });
    });

    it('should render with custom overlay className', () => {
      render(<Modal {...defaultProps} isOpen={true} overlayClassName="custom-overlay" />);

      const overlay = screen.getByTestId('modal-overlay');
      expect(overlay).toHaveClass('custom-overlay');
    });
  });

  // ========== Interaction Tests ==========

  describe('Interactions', () => {
    it('should call onClose when close button is clicked', async () => {
      const user = userEvent.setup();
      render(<Modal {...defaultProps} isOpen={true} />);

      const closeButton = screen.getByLabelText('关闭对话框');
      await user.click(closeButton);

      // Wait for animation delay
      await waitFor(
        () => {
          expect(defaultProps.onClose).toHaveBeenCalledTimes(1);
        },
        { timeout: 200 }
      );
    });

    it('should call onClose when ESC key is pressed', async () => {
      const user = userEvent.setup();
      render(<Modal {...defaultProps} isOpen={true} />);

      await user.keyboard('{Escape}');

      // Wait for animation delay
      await waitFor(
        () => {
          expect(defaultProps.onClose).toHaveBeenCalledTimes(1);
        },
        { timeout: 200 }
      );
    });

    it('should not call onClose when ESC key is pressed if enableEscClose is false', async () => {
      const user = userEvent.setup();
      render(<Modal {...defaultProps} isOpen={true} enableEscClose={false} />);

      await user.keyboard('{Escape}');

      expect(defaultProps.onClose).not.toHaveBeenCalled();
    });

    it('should call onClose when backdrop is clicked', async () => {
      const user = userEvent.setup();
      render(<Modal {...defaultProps} isOpen={true} />);

      const overlay = screen.getByTestId('modal-overlay');
      await user.click(overlay);

      // Wait for animation delay
      await waitFor(
        () => {
          expect(defaultProps.onClose).toHaveBeenCalledTimes(1);
        },
        { timeout: 200 }
      );
    });

    it('should not call onClose when modal content is clicked', async () => {
      const user = userEvent.setup();
      render(<Modal {...defaultProps} isOpen={true} />);

      const modal = screen.getByRole('dialog');
      await user.click(modal);

      expect(defaultProps.onClose).not.toHaveBeenCalled();
    });

    it('should not call onClose when closeOnBackdropClick is false', async () => {
      const user = userEvent.setup();
      render(<Modal {...defaultProps} isOpen={true} closeOnBackdropClick={false} />);

      const overlay = screen.getByTestId('modal-overlay');
      await user.click(overlay);

      expect(defaultProps.onClose).not.toHaveBeenCalled();
    });

    it('should call onBeforeClose and wait for result', async () => {
      const onBeforeClose = vi.fn().mockResolvedValue(true);
      const user = userEvent.setup();

      render(
        <Modal 
          {...defaultProps} 
          isOpen={true} 
          onBeforeClose={onBeforeClose}
        />
      );

      const closeButton = screen.getByLabelText('关闭对话框');
      await user.click(closeButton);

      expect(onBeforeClose).toHaveBeenCalledTimes(1);

      // Wait for animation delay
      await waitFor(
        () => {
          expect(defaultProps.onClose).toHaveBeenCalledTimes(1);
        },
        { timeout: 200 }
      );
    });

    it('should show confirm dialog when onBeforeClose returns false', async () => {
      const onBeforeClose = vi.fn().mockResolvedValue(false);
      const user = userEvent.setup();

      render(
        <Modal 
          {...defaultProps} 
          isOpen={true} 
          onBeforeClose={onBeforeClose}
        />
      );

      const closeButton = screen.getByLabelText('关闭对话框');
      await user.click(closeButton);

