import React, {
  forwardRef,
  useState,
  useRef,
  useEffect,
  useCallback,
  useMemo,
  KeyboardEvent,
  MouseEvent,
  ChangeEvent,
  FocusEvent
} from 'react';
import { Controller } from 'react-hook-form';

import type { SelectProps, SelectOption } from './Select.types';
import { filterOptions, getSelectedOptions, calculateDropdownPosition } from './Select.utils';
import { SelectDropdown } from './SelectDropdown';
import { SelectInput } from './SelectInput';

import { useDebounce } from '@/shared/ui/hooks/useDebounce';
import './Select.css';

/**
 * Dropdown position type
 */
type DropdownPosition = 'down' | 'up';

/**
 * Select Component
 *
 * A cyberpunk-themed dropdown select with support for:
 * - Single/multiple selection
 * - Search/filter functionality
 * - Keyboard navigation (Enter, Space, Escape, Arrow keys)
 * - Intelligent dropdown positioning (up/down based on viewport)
 * - Click outside to close
 * - Accessibility attributes (ARIA)
 * - React Hook Form integration
 * - Autocomplete mode with remote search
 * - Create new options
 * - Loading state
 * - Debounced search
 */
const Select = React.memo(forwardRef<HTMLDivElement, SelectProps>(({
  name,
  label,
  options = [],
  value,
  onChange,
  placeholder = 'Select...',
  disabled = false,
  required = false,
  searchable = false,
  multiple = false,
  error,
  helperText,
  className = '',
  size = 'medium',
  control,
  rules,
  mode = 'default',
  allowCreate = false,
  onSearch,
  onCreate,
  loading = false,
  searchDebounce = 300,
  noOptionsMessage = 'No options found',
  ...props
}, ref) => {
  const [isOpen, setIsOpen] = useState<boolean>(false);
  const [searchTerm, setSearchTerm] = useState<string>('');
  const [dropdownPosition, setDropdownPosition] = useState<DropdownPosition>('down');
  const [focusedIndex, setFocusedIndex] = useState<number>(-1);
  const [selectedValues, setSelectedValues] = useState<(string | number)[]>(
    multiple ? (Array.isArray(value) ? value : []) : (value !== undefined ? [value] : [])
  );

  const dropdownRef = useRef<HTMLDivElement>(null);
  const triggerRef = useRef<HTMLDivElement>(null);
  const searchInputRef = useRef<HTMLInputElement>(null);
  const optionsRef = useRef<HTMLDivElement[]>([]);

  const labelId = React.useId();
  const triggerId = React.useId();
  const isInvalid = Boolean(error);

  // Update selected values when value prop changes
  useEffect(() => {
    if (multiple) {
      setSelectedValues(Array.isArray(value) ? value : []);
    } else if (value !== undefined) {
      setSelectedValues([value]);
    }
  }, [value, multiple]);

  // Calculate dropdown position based on viewport
  useEffect(() => {
    if (!isOpen || !dropdownRef.current || !triggerRef.current) return;

    const dropdown = dropdownRef.current;
    const trigger = triggerRef.current;

    const triggerRect = trigger.getBoundingClientRect();
    const dropdownHeight = dropdown.offsetHeight || 240;
    const viewportHeight = window.innerHeight;

    setDropdownPosition(calculateDropdownPosition(triggerRect, dropdownHeight, viewportHeight));
  }, [isOpen]);

  // Debounce search term for autocomplete mode
  const debouncedSearchTerm = useDebounce(searchTerm, searchDebounce);

  // Call onSearch when debounced search term changes (autocomplete mode)
  useEffect(() => {
    if (mode === 'autocomplete' && onSearch && debouncedSearchTerm !== undefined) {
      onSearch(debouncedSearchTerm);
    }
  }, [mode, onSearch, debouncedSearchTerm]);

  // Filter options based on search term
  // In autocomplete mode, we don't filter locally - the parent controls options
  const filteredOptions = useMemo(() => {
    if (mode === 'autocomplete') {
      return options;
    }
    return filterOptions(options, searchTerm, searchable);
  }, [mode, options, searchTerm, searchable]);

  // Handle creating a new option
  const handleCreateOption = useCallback((label: string) => {
    if (onCreate && label.trim()) {
      onCreate(label.trim());
    }
    setSearchTerm('');
    setFocusedIndex(-1);
  }, [onCreate]);

  // Get selected option(s) label(s)
  const selectedOptions = useMemo(() => {
    return getSelectedOptions(options, selectedValues);
  }, [options, selectedValues]);

  // Close dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: Event) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsOpen(false);
        setSearchTerm('');
        setFocusedIndex(-1);
      }
    };

    if (isOpen) {
      document.addEventListener('mousedown', handleClickOutside);
    }

    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [isOpen]);

  // Handle option selection
  const handleSelectOption = useCallback((optionValue: string | number) => {
    let newValues: (string | number)[];

    if (multiple) {
      if (selectedValues.includes(optionValue)) {
        newValues = selectedValues.filter(v => v !== optionValue);
      } else {
        newValues = [...selectedValues, optionValue];
      }
      setSelectedValues(newValues);
      onChange?.(newValues);
      // Close dropdown after selection in multiple mode
      setIsOpen(false);
    } else {
      newValues = [optionValue];
      setSelectedValues(newValues);
      onChange?.(optionValue);
      setIsOpen(false);
    }
    setSearchTerm('');
    setFocusedIndex(-1);
  }, [selectedValues, multiple, onChange]);

  // Handle removing selected option (for multiple select)
  const handleRemoveOption = useCallback((event: MouseEvent, optionValue: string | number) => {
    event.stopPropagation();
    const newValues = selectedValues.filter(v => v !== optionValue);
    setSelectedValues(newValues);
    onChange?.(newValues);
  }, [selectedValues, onChange]);

  // Handle search term change
  const handleSearchChange = useCallback((e: ChangeEvent<HTMLInputElement>) => {
    setSearchTerm(e.target.value);
    setFocusedIndex(-1);
  }, []);

  // Handle search input click
  const handleSearchClick = useCallback((e: MouseEvent<HTMLInputElement>) => {
    e.stopPropagation();
  }, []);

  // Handle trigger click
  const handleTriggerClick = useCallback(() => {
    if (!disabled) {
      setIsOpen(prev => !prev);
    }
  }, [disabled]);

  // Handle keyboard navigation
  const handleKeyDown = useCallback((event: KeyboardEvent<HTMLDivElement>) => {
    if (disabled) return;

    const visibleOptions = filteredOptions.filter(opt => !opt.disabled);

    switch (event.key) {
      case 'Enter':
      case ' ':
        event.preventDefault();
        if (isOpen && focusedIndex >= 0 && focusedIndex < visibleOptions.length) {
          handleSelectOption(visibleOptions[focusedIndex].value);
        } else {
          setIsOpen(prev => !prev);
        }
        break;
      case 'Escape':
        setIsOpen(false);
        setSearchTerm('');
        setFocusedIndex(-1);
        break;
      case 'ArrowDown':
        event.preventDefault();
        if (!isOpen) {
          setIsOpen(true);
        } else {
          setFocusedIndex(prev => {
            if (visibleOptions.length === 0) return -1;
            return prev < visibleOptions.length - 1 ? prev + 1 : 0;
          });
        }
        break;
      case 'ArrowUp':
        event.preventDefault();
        if (isOpen) {
          setFocusedIndex(prev => {
            if (visibleOptions.length === 0) return -1;
            return prev > 0 ? prev - 1 : visibleOptions.length - 1;
          });
        }
        break;
      case 'Tab':
        setIsOpen(false);
        break;
    }
  }, [disabled, isOpen, focusedIndex, filteredOptions, handleSelectOption]);

  // Handle focus
  const handleFocus = useCallback((e: FocusEvent<HTMLDivElement>) => {
    if (searchable && isOpen && searchInputRef.current) {
      searchInputRef.current.focus();
    }
  }, [searchable, isOpen]);

  // Scroll focused option into view
  useEffect(() => {
    if (focusedIndex >= 0) {
      // Scroll the focused visible option into view
      const visibleOptions = filteredOptions.filter(opt => !opt.disabled);
      if (focusedIndex < visibleOptions.length) {
        const focusedOption = visibleOptions[focusedIndex];
        const optionIndex = filteredOptions.findIndex(opt => opt.value === focusedOption.value);
        const optionElement = optionsRef.current[optionIndex];
        if (optionElement && typeof optionElement.scrollIntoView === 'function') {
          optionElement.scrollIntoView({ block: 'nearest' });
        }
      }
    }
  }, [focusedIndex, filteredOptions]);

  const wrapperClass = [
    'cyber-select-wrapper',
    `cyber-select-wrapper--${size}`,
    isInvalid && 'cyber-select-wrapper--invalid',
    disabled && 'cyber-select-wrapper--disabled',
    isOpen && 'cyber-select-wrapper--open'
  ].filter(Boolean).join(' ');

  const containerClass = [
    'cyber-select',
    className
  ].filter(Boolean).join(' ');

  // Determine aria-describedby value
  const ariaDescribedBy = [
    isInvalid ? `${triggerId}-error` : null,
    helperText && !isInvalid ? `${triggerId}-helper` : null
  ].filter(Boolean).join(' ') || undefined;

  // Render with React Hook Form Controller if control is provided
  if (control) {
    return (
      <Controller
        name={name}
        control={control}
        rules={rules}
        render={({ field: { onChange: controllerOnChange, value: controllerValue, onBlur }, fieldState: { error: fieldError } }) => (
          <div className={containerClass} ref={ref} {...props}>
            <div className={wrapperClass} ref={dropdownRef}>
              <SelectInput
                id={triggerId}
                label={label}
                labelId={labelId}
                placeholder={placeholder}
                disabled={disabled}
                multiple={multiple}
                isOpen={isOpen}
                isInvalid={isInvalid}
                selectedOptions={selectedOptions}
                searchable={searchable}
                onTriggerClick={handleTriggerClick}
                onRemoveOption={handleRemoveOption}
                onKeyDown={handleKeyDown}
                onFocus={handleFocus}
                onBlur={onBlur}
                triggerRef={triggerRef}
                ariaDescribedBy={ariaDescribedBy}
                required={required}
              />

              <SelectDropdown
                isOpen={isOpen}
                position={dropdownPosition}
                searchable={searchable}
                searchTerm={searchTerm}
                filteredOptions={filteredOptions}
                selectedValues={selectedValues}
                focusedIndex={focusedIndex}
                multiple={multiple}
                onSearchChange={handleSearchChange}
                onSearchClick={handleSearchClick}
                onSelectOption={handleSelectOption}
                searchInputRef={searchInputRef}
                optionsRef={optionsRef}
                allowCreate={allowCreate && !multiple}
                onCreate={handleCreateOption}
                noOptionsMessage={noOptionsMessage}
                loading={loading}
              />
            </div>

            {fieldError && (
              <p id={`${triggerId}-error`} className="cyber-select__error" role="alert">
                {fieldError.message}
              </p>
            )}

            {helperText && !fieldError && (
              <p id={`${triggerId}-helper`} className="cyber-select__helper">
                {helperText}
              </p>
            )}
          </div>
        )}
      />
    );
  }

  // Render without React Hook Form Controller
  return (
    <div className={containerClass} ref={ref} {...props}>
      <div className={wrapperClass} ref={dropdownRef}>
        <SelectInput
          id={triggerId}
          label={label}
          labelId={labelId}
          placeholder={placeholder}
          disabled={disabled}
          multiple={multiple}
          isOpen={isOpen}
          isInvalid={isInvalid}
          selectedOptions={selectedOptions}
          searchable={searchable}
          onTriggerClick={handleTriggerClick}
          onRemoveOption={handleRemoveOption}
          onKeyDown={handleKeyDown}
          onFocus={handleFocus}
          triggerRef={triggerRef}
          ariaDescribedBy={ariaDescribedBy}
          required={required}
        />

        <SelectDropdown
          isOpen={isOpen}
          position={dropdownPosition}
          searchable={searchable}
          searchTerm={searchTerm}
          filteredOptions={filteredOptions}
          selectedValues={selectedValues}
          focusedIndex={focusedIndex}
          multiple={multiple}
          onSearchChange={handleSearchChange}
          onSearchClick={handleSearchClick}
          onSelectOption={handleSelectOption}
          searchInputRef={searchInputRef}
          optionsRef={optionsRef}
          allowCreate={allowCreate && !multiple}
          onCreate={handleCreateOption}
          noOptionsMessage={noOptionsMessage}
          loading={loading}
        />
      </div>

      {isInvalid && (
        <p id={`${triggerId}-error`} className="cyber-select__error" role="alert">
          {error}
        </p>
      )}

      {helperText && !isInvalid && (
        <p id={`${triggerId}-helper`} className="cyber-select__helper">
          {helperText}
        </p>
      )}
    </div>
  );
}));

// Set display name for debugging
Select.displayName = 'Select';

export default Select;

import { FieldValues, FieldPath } from 'react-hook-form';

import type { Size } from '@/shared/ui/types/common';

export interface SelectOption {
  value: string | number;
  label: string;
  disabled?: boolean;
}

/** Select mode - default for local filtering, autocomplete for remote search */
export type SelectMode = 'default' | 'autocomplete';

export interface SelectProps<TFieldValues extends FieldValues = FieldValues> {
  name: FieldPath<TFieldValues>;
  label?: string;
  options: SelectOption[];
  value?: string | number | (string | number)[];
  onChange?: (value: string | number | (string | number)[]) => void;
  placeholder?: string;
  disabled?: boolean;
  required?: boolean;
  searchable?: boolean;
  multiple?: boolean;
  error?: string;
  helperText?: string;
  className?: string;
  size?: Size;
  control?: unknown;
  rules?: unknown;
  /** Select mode - 'default' for local filtering, 'autocomplete' for remote search */
  mode?: SelectMode;
  /** Allow creating new options (only for single select) */
  allowCreate?: boolean;
  /** Callback when searching (for autocomplete mode) */
  onSearch?: (searchTerm: string) => void;
  /** Callback when creating a new option */
  onCreate?: (label: string) => void;
  /** Loading state (for autocomplete mode) */
  loading?: boolean;
  /** Debounce delay for search in milliseconds (default: 300) */
  searchDebounce?: number;
  /** Custom message when no options match */
  noOptionsMessage?: string;
}

/**
 * Unified Table Component - Powered by TanStack Table
 * 
 * A high-performance, feature-rich table component that replaces multiple
 * existing table implementations with a unified API.
 * 
 * Key Features:
 * - TanStack Table for optimal performance
 * - Virtual scrolling for large datasets
 * - Column pinning (left/right fixed columns)
 * - Editable cells with custom components
 * - Advanced sorting and filtering
 * - Row selection with multi-select support
 * - Responsive design with theme customization
 */

import {
  useReactTable,
  getCoreRowModel,
  getSortedRowModel,
  getFilteredRowModel,
  getPaginationRowModel,
  flexRender,
  ColumnFiltersState,
  SortingState,
  PaginationState,
  RowSelectionState,
  ColumnPinningState,
} from '@tanstack/react-table';
import { useVirtualizer } from '@tanstack/react-virtual';
import React, { 
  useMemo, 
  useCallback, 
  useState, 
  useRef, 
  useEffect,
  forwardRef 
} from 'react';

import type {
  TableProps,
  TableColumn,
  CellContext,
  TableHeaderProps,
  TableBodyProps,
  TableFooterProps,
  TableRowProps,
  TableCellProps,
  TableHeadProps,
  PaginationProps,
  VirtualScrollMetrics,
} from './Table.types';
import { TableBody } from './TableBody';
import { TableCell } from './TableCell';
import { TableEmptyState } from './TableEmptyState';
import { TableFilter } from './TableFilter';
import { TableFooter } from './TableFooter';
import { TableHeader } from './TableHeader';
import { TableLoadingState } from './TableLoadingState';
import { TablePagination } from './TablePagination';
import { TableRegularRows } from './TableRegularRows';
import { TableRow } from './TableRow';
import { TableSort } from './TableSort';
import { TableVirtualizedRows } from './TableVirtualizedRows';
import { useTableHandlers } from './useTableHandlers';
import { useTableRender } from './useTableRender';
import { useTableVirtualScroll } from './useTableVirtualScroll';
import './Table.css';

// ============================================================================
// Main Table Component
// ============================================================================
// ============================================================================
// Main Table Component
// ============================================================================

const Table = React.memo(<TData extends object = any>({
  data,
  columns,
  variant = 'default',
  size = 'md',
  striped = true,
  hoverable = true,
  bordered = false,
  selectable = false,
  onSelectionChange,
  initialSelectedIds = [],
  sortable = true,
  onSortChange,
  initialSorting = [],
  filterable = true,
  onFilterChange,
  initialFilters = [],
  pagination = true,
  pageSize = 10,
  currentPage = 1,
  onPageChange,
  pageSizeOptions = [10, 20, 50, 100],
  virtual = false,
  rowHeight = 50,
  maxHeight = 600,
  overscan = 10,
  dynamicRowHeight = false,
  onVirtualScrollMetrics,
  editable = false,
  onEdit,
  onRowClick,
  onRowDoubleClick,
  onCellClick,
  loading = false,
  loadingComponent,
  empty = false,
  emptyComponent,
  className = '',
  style,
  tableClassName = '',
  headerClassName = '',
  bodyClassName = '',
  theme = 'light',
}: TableProps<TData>) => {
  // ============================================================================
  // State Management
  // ============================================================================

  const [sorting, setSorting] = useState<SortingState>(initialSorting);
  const [columnFilters, setColumnFilters] = useState<ColumnFiltersState>(initialFilters);
  const [rowSelection, setRowSelection] = useState<RowSelectionState>(() => {
    const selection: RowSelectionState = {};
    initialSelectedIds.forEach((id) => {
      selection[String(id)] = true;
    });
    return selection;
  });
  const [columnPinning, setColumnPinning] = useState<ColumnPinningState>({ left: [], right: [] });
  const [paginationState, setPaginationState] = useState<PaginationState>({
    pageIndex: currentPage - 1,
    pageSize,
  });
  const [editingCell, setEditingCell] = useState<{ rowIndex: number; columnId: string } | null>(null);

  // ============================================================================
  // Column Definition
  // ============================================================================

  const tableColumns = useMemo(() => {
    const cols: TableColumn<TData>[] = [...columns];

    // Add selection column if selectable
    if (selectable) {
      cols.unshift({
        id: 'select',
        header: ({ table }) => (
          <input
            type="checkbox"
            checked={table.getIsAllRowsSelected()}
            onChange={table.getToggleAllRowsSelectedHandler()}
            className="table-checkbox"
            aria-label="Select all rows"
          />
        ),
        cell: ({ row }) => (
          <input
            type="checkbox"
            checked={row.getIsSelected()}
            onChange={row.getToggleSelectedHandler()}
            className="table-checkbox"
            aria-label={`Select row ${row.index + 1}`}
          />
        ),
        enableSorting: false,
        enableFiltering: false,
        size: 40,
      } as TableColumn<TData>);
    }

    return cols.map((col) => ({
      ...col,
      enableSorting: col.sortable !== false && sortable,
      enableFiltering: col.filterable !== false && filterable,
      size: col.width || 'auto',
      minSize: col.minWidth || 40,
      maxSize: col.maxWidth || 1000,
    }));
  }, [columns, selectable, sortable, filterable]);

  // ============================================================================
  // Table Instance
  // ============================================================================

  const table = useReactTable({
    data,
    columns: tableColumns,
    state: {
      sorting,
      columnFilters,
      rowSelection,
      columnPinning,
      pagination: paginationState,
    },
    onSortingChange: (updater) => {
      const newSorting = typeof updater === 'function' ? updater(sorting) : updater;
      setSorting(newSorting);
      onSortChange?.(newSorting);
    },
    onColumnFiltersChange: (updater) => {
      const newFilters = typeof updater === 'function' ? updater(columnFilters) : updater;
      setColumnFilters(newFilters);
      onFilterChange?.(newFilters as unknown as Record<string, unknown>);
    },
    onRowSelectionChange: (updater) => {
      const newSelection = typeof updater === 'function' ? updater(rowSelection) : updater;
      setRowSelection(newSelection);

      // Notify parent of selection changes
      if (onSelectionChange) {
        const selectedRows = table
          .getSelectedRowModel()
          .rows.map((row) => row.original);
        onSelectionChange(selectedRows);
      }
    },
    onColumnPinningChange: setColumnPinning,
    onPaginationChange: (updater) => {
      const newPagination = typeof updater === 'function' ? updater(paginationState) : updater;
      setPaginationState(newPagination);
      onPageChange?.(newPagination.pageIndex + 1, newPagination.pageSize);
    },
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
    getPaginationRowModel: pagination ? getPaginationRowModel() : undefined,
    enableRowSelection: selectable,
    enableMultiRowSelection: true,
    enableSubRowSelection: false,
  });

  // ============================================================================
  // Virtual Scrolling
  // ============================================================================

  const tableContainerRef = useRef<HTMLDivElement>(null);
  const renderStartTimeRef = useRef<number>(0);

  const { rows } = table.getRowModel();

  const rowVirtualizer = useVirtualizer({
    count: rows.length,
    getScrollElement: () => tableContainerRef.current,
    estimateSize: useCallback(
      (index: number) => {
        // Support dynamic row height estimation based on content
        if (dynamicRowHeight) {
          const row = rows[index];
          if (row) {
            // Estimate based on content length (basic heuristic)
            const cellCount = row.getVisibleCells().length;
            return Math.max(rowHeight, Math.min(rowHeight * 2, cellCount * 20));
          }
        }
        return rowHeight;
      },
      [dynamicRowHeight, rows, rowHeight]
    ),
    overscan,
    measureElement: dynamicRowHeight
      ? (element) => element?.getBoundingClientRect().height
      : undefined,
  });

  const virtualRows = virtual ? rowVirtualizer.getVirtualItems() : [];
  const totalSize = virtual ? rowVirtualizer.getTotalSize() : 0;

  // Report virtual scroll metrics
  useEffect(() => {
    if (virtual && onVirtualScrollMetrics) {
      const metrics: VirtualScrollMetrics = {
        totalRows: rows.length,
        visibleRows: virtualRows.length,
        scrollOffset: rowVirtualizer.scrollOffset ?? 0,
        estimatedRowHeight: rowHeight,
        renderTime: renderStartTimeRef.current > 0 
          ? performance.now() - renderStartTimeRef.current 
          : undefined,
      };
      onVirtualScrollMetrics(metrics);
    }
  }, [virtual, onVirtualScrollMetrics, rows.length, virtualRows.length, rowVirtualizer.scrollOffset, rowHeight]);

  // Track render start time for performance measurement
  useEffect(() => {
    if (virtual) {
      renderStartTimeRef.current = performance.now();
    }
  }, [virtual, virtualRows]);

  // ============================================================================
  // Event Handlers
  // ============================================================================

  const handleRowClick = useCallback(
    (row: TData, event: React.MouseEvent) => {
      onRowClick?.(row, event);
    },
    [onRowClick]
  );

  const handleRowDoubleClick = useCallback(
    (row: TData, event: React.MouseEvent) => {
      onRowDoubleClick?.(row, event);
    },
    [onRowDoubleClick]
  );

  const handleCellClick = useCallback(
    (cell: CellContext<TData>, event: React.MouseEvent) => {
      onCellClick?.(cell, event);
    },
    [onCellClick]
  );

  const handleCellEdit = useCallback(
    (row: TData, columnId: string, value: unknown) => {
      onEdit?.(row, columnId, value);
      setEditingCell(null);
    },
    [onEdit]
  );

  // ============================================================================
  // Render Helpers
  // ============================================================================

  const renderCell = useCallback(
    (cell: any, rowIndex: number) => {
      const column = cell.column;
      const isEditing = editingCell?.rowIndex === rowIndex && editingCell?.columnId === column.id;
      const columnDef = column.columnDef as TableColumn<TData>;

      if (editable && columnDef.editable && isEditing) {
        return (
          <div className="table-cell-edit">
            {columnDef.editComponent ? (
              columnDef.editComponent({
                value: cell.getValue(),
                row: cell.row,
                column,
                onChange: (value) => cell.setValue(value),
                onSave: () => handleCellEdit(cell.row.original, column.id, cell.getValue()),
                onCancel: () => setEditingCell(null),
              })
            ) : (
              <input
                type="text"
                defaultValue={cell.getValue() as string}
                onBlur={() => handleCellEdit(cell.row.original, column.id, cell.getValue())}
                onKeyDown={(e) => {
                  if (e.key === 'Enter') {
                    handleCellEdit(cell.row.original, column.id, cell.getValue());
                  } else if (e.key === 'Escape') {
                    setEditingCell(null);
                  }
                }}
                autoFocus
                className="table-input"
              />
            )}
          </div>
        );
      }

      if (columnDef.cellRenderer) {
        return columnDef.cellRenderer({
          cell,
          row: cell.row,
          column,
          value: cell.getValue(),
        });
      }

      return flexRender(column.columnDef.cell, cell.getContext());
    },
    [editable, editingCell, handleCellEdit]
  );

  const renderHeader = useCallback(
    (header: any) => {
      const column = header.column;
      const columnDef = column.columnDef as TableColumn<TData>;

      if (columnDef.headerRenderer) {
        return columnDef.headerRenderer({
          column,
          header: columnDef.header || '',
        });
      }

      return flexRender(column.columnDef.header, header.getContext());
    },
    []
  );

  // ============================================================================
  // Effects
  // ============================================================================

  // Sync external pagination state
  useEffect(() => {
    setPaginationState({
      pageIndex: currentPage - 1,
      pageSize,
    });
  }, [currentPage, pageSize]);

  // Setup column pinning
  useEffect(() => {
    const leftPins: string[] = [];
    const rightPins: string[] = [];

    tableColumns.forEach((col) => {
      if (col.fixed === 'left') {
        leftPins.push(col.id || col.accessorKey as string);
      } else if (col.fixed === 'right') {
        rightPins.push(col.id || col.accessorKey as string);
      }
    });

    setColumnPinning({ left: leftPins, right: rightPins });
  }, [tableColumns]);

  // ============================================================================
  // Render
  // ============================================================================

  const tableClasses = [
    'table',
    `table--${variant}`,
    `table--${size}`,
    `table--${theme}`,
    striped && 'table--striped',
    hoverable && 'table--hoverable',
    bordered && 'table--bordered',
    className,
  ].filter(Boolean).join(' ');

  const displayRows = virtual ? rows : table.getRowModel().rows;

  return (
    <div className={`table-wrapper ${className}`} style={style}>
      <div
        ref={tableContainerRef}
        className="table-container"
        style={{
          maxHeight: virtual ? maxHeight : undefined,
          overflow: virtual ? 'auto' : 'visible',
        }}
      >
        <table className={`${tableClasses} ${tableClassName}`}>
          <TableHeader className={headerClassName}>
            {table.getHeaderGroups().map((headerGroup) => (
              <tr key={headerGroup.id}>
                {headerGroup.headers.map((header) => {
                  const columnDef = header.column.columnDef as TableColumn<TData>;
                  const isPinnedLeft = header.column.getIsPinned() === 'left';
                  const isPinnedRight = header.column.getIsPinned() === 'right';
                  const isPinned = isPinnedLeft || isPinnedRight;

                  // Column grouping support - check if this is a group header
                  const isGroupHeader = !header.isPlaceholder && header.colSpan > 1;
                  const colSpan = header.colSpan;
                  const rowSpan = header.rowSpan || 1;

                  return (
                    <th
                      key={header.id}
                      className={[
                        'table-th',
                        columnDef.align && `table-th--${columnDef.align}`,
                        header.column.getCanSort() && 'table-th--sortable',
                        isPinned && 'table-th--pinned',
                        isPinnedLeft && 'table-th--pinned-left',
                        isPinnedRight && 'table-th--pinned-right',
                        isGroupHeader && 'table-th--group',
                      ].filter(Boolean).join(' ')}
                      style={{
                        width: header.getSize() !== 150 ? header.getSize() : undefined,
                        left: isPinnedLeft ? header.getStart() : undefined,
                        right: isPinnedRight ? header.getTotalRight() : undefined,
                      }}
                      colSpan={colSpan}
                      rowSpan={rowSpan}
                      onClick={
                        header.column.getCanSort()
                          ? header.column.getToggleSortingHandler()
                          : undefined
                      }
                    >
                      <div className="table-th-content">
                        {renderHeader(header)}
                        {header.column.getIsSorted() && (
                          <span className="table-sort-indicator">
                            {header.column.getIsSorted() === 'asc' ? '↑' : '↓'}
                          </span>
                        )}
                      </div>
                      {!isGroupHeader && !header.isPlaceholder && (
                        <div
                          className="table-resizer"
                          onMouseDown={header.getResizeHandler()}
                          onClick={(e) => e.stopPropagation()}
                        />
                      )}
                    </th>
                  );
                })}
              </tr>
            ))}
          </TableHeader>

          <TableBody className={bodyClassName}>
            {loading ? (
              <TableLoadingState
                colSpan={table.getAllColumns().length}
                loadingComponent={loadingComponent}
              />
            ) : displayRows.length === 0 ? (
              <TableEmptyState
                colSpan={table.getAllColumns().length}
                emptyComponent={emptyComponent}
              />
            ) : (
              <>
                {virtual ? (
                  <TableVirtualizedRows
                    rows={rows}
                    virtualRows={virtualRows}
                    totalSize={totalSize}
                    rowVirtualizer={rowVirtualizer}
                    dynamicRowHeight={dynamicRowHeight}
                    editable={editable}
                    editingCell={editingCell}
                    setEditingCell={setEditingCell}
                    renderCell={renderCell}
                    onRowClick={handleRowClick}
                    onRowDoubleClick={handleRowDoubleClick}
                    onCellClick={handleCellClick}
                  />
                ) : (
                  <TableRegularRows
                    rows={displayRows}
                    editable={editable}
                    editingCell={editingCell}
                    setEditingCell={setEditingCell}
                    renderCell={renderCell}
                    onRowClick={handleRowClick}
                    onRowDoubleClick={handleRowDoubleClick}
                    onCellClick={handleCellClick}
                  />
                )}
              </>
            )}
          </TableBody>
        </table>
      </div>

      {pagination && !loading && displayRows.length > 0 && (
        <TablePagination
          currentPage={paginationState.pageIndex + 1}
          pageSize={paginationState.pageSize}
          total={table.getFilteredRowModel().rows.length}
          pageSizeOptions={pageSizeOptions}
          onPageChange={(page, size) => {
            setPaginationState({ pageIndex: page - 1, pageSize: size });
            onPageChange?.(page, size);
          }}
          showTotal={(total, range) => (
            <span>
              {range[0]}-{range[1]} of {total} items
            </span>
          )}
        />
      )}
    </div>
  );
});

