import React, { useState } from 'react';

import { TableFilterProps, RowData } from './Table.types';

/**
 * TableFilter Component
 * 
 * Renders filter controls for a column with support for:
 * - Text filtering
 * - Select filtering
 * - Date filtering
 * - Number filtering
 */
export const TableFilter = React.memo(<TData extends RowData>({
  column,
  value,
  onChange,
}: TableFilterProps<TData>) => {
  const [localValue, setLocalValue] = useState(value as string || '');

  const handleChange = (newValue: unknown) => {
    setLocalValue(newValue as string);
    onChange(newValue);
  };

  const filterType = column.filterType || 'text';

  if (filterType === 'select' && column.filterOptions) {
    return (
      <select
        value={localValue as string}
        onChange={(e) => handleChange(e.target.value)}
        className="table-filter-select"
      >
        <option value="">All</option>
        {column.filterOptions.map((option) => (
          <option key={option.value} value={option.value}>
            {option.label}
          </option>
        ))}
      </select>
    );
  }

  if (filterType === 'date') {
    return (
      <input
        type="date"
        value={localValue as string}
        onChange={(e) => handleChange(e.target.value)}
        className="table-filter-input"
      />
    );
  }

  if (filterType === 'number') {
    return (
      <input
        type="number"
        value={localValue as string}
        onChange={(e) => handleChange(e.target.value)}
        className="table-filter-input"
        placeholder="Filter..."
      />
    );
  }

  // Default: text filter
  return (
    <input
      type="text"
      value={localValue as string}
      onChange={(e) => handleChange(e.target.value)}
      className="table-filter-input"
      placeholder="Filter..."
    />
  );
}) as <TData extends RowData>(props: TableFilterProps<TData>) => React.JSX.Element;

import { flexRender } from '@tanstack/react-table';
import React from 'react';

import { TableHeaderProps, TableColumn, RowData } from './Table.types';

/**
 * TableHeader Component
 * 
 * Renders the header section of the table with support for:
 * - Column grouping
 * - Sorting indicators
 * - Column resizing
 * - Fixed columns
 * - Custom header rendering
 */
export const TableHeader = React.memo(<TData extends RowData>({
  className = '',
  children,
}: TableHeaderProps) => {
  return <thead className={`table-thead ${className}`}>{children}</thead>;
}) as <TData extends RowData>(props: TableHeaderProps) => React.JSX.Element;
/**
 * TableHead Component
 * 
 * Individual table header cell with sorting and resizing support
 */
export const TableHead = React.memo(<TData extends RowData>({
  header,
  column,
  sortable = false,
  onSort,
  renderHeader,
  className = '',
}: {
  header: any;
  column: TableColumn<TData>;
  sortable?: boolean;
  onSort?: (columnId: string) => void;
  renderHeader?: (header: any) => React.ReactNode;
  className?: string;
}) => {
  const columnDef = column as TableColumn<TData>;
  const isPinnedLeft = header.column.getIsPinned() === 'left';
  const isPinnedRight = header.column.getIsPinned() === 'right';
  const isPinned = isPinnedLeft || isPinnedRight;

  // Column grouping support
  const isGroupHeader = !header.isPlaceholder && header.colSpan > 1;
  const colSpan = header.colSpan;
  const rowSpan = header.rowSpan || 1;

  const handleClick = () => {
    if (sortable && header.column.getCanSort()) {
      onSort?.(header.column.id);
    }
  };

  const headClasses = [
    'table-th',
    columnDef.align && `table-th--${columnDef.align}`,
    header.column.getCanSort() && 'table-th--sortable',
    isPinned && 'table-th--pinned',
    isPinnedLeft && 'table-th--pinned-left',
    isPinnedRight && 'table-th--pinned-right',
    isGroupHeader && 'table-th--group',
    className,
  ].filter(Boolean).join(' ');

  const style: React.CSSProperties = {
    width: header.getSize() !== 150 ? header.getSize() : undefined,
    left: isPinnedLeft ? header.getStart() : undefined,
    right: isPinnedRight ? header.getTotalRight() : undefined,
  };

  return (
    <th
      className={headClasses}
      style={style}
      colSpan={colSpan}
      rowSpan={rowSpan}
      onClick={sortable ? handleClick : undefined}
    >
      <div className="table-th-content">
        {renderHeader ? renderHeader(header) : flexRender(column.header, header.getContext())}
        {header.column.getIsSorted() && (
          <span className="table-sort-indicator">
            {header.column.getIsSorted() === 'asc' ? '↑' : '↓'}
          </span>
        )}
      </div>
      {!isGroupHeader && !header.isPlaceholder && (
        <div
          className="table-resizer"
          onMouseDown={header.getResizeHandler()}
          onClick={(e) => e.stopPropagation()}
        />
      )}
    </th>
  );
}) as <TData extends RowData>(props: {
  header: any;
  column: TableColumn<TData>;
  sortable?: boolean;
  onSort?: (columnId: string) => void;
  renderHeader?: (header: any) => React.ReactNode;
  className?: string;
}) => React.JSX.Element;

import { Row, RowData } from '@tanstack/react-table';
import React, { useCallback } from 'react';

import { TableColumn, CellContext } from './Table.types';

interface TableRegularRowsProps<TData extends RowData> {
  rows: Row<TData>[];
  editable: boolean;
  editingCell: { rowIndex: number; columnId: string } | null;
  setEditingCell: React.Dispatch<React.SetStateAction<{ rowIndex: number; columnId: string } | null>>;
  renderCell: (cell: any, rowIndex: number) => React.ReactNode;
  onRowClick?: (row: TData, event: React.MouseEvent) => void;
  onRowDoubleClick?: (row: TData, event: React.MouseEvent) => void;
  onCellClick?: (cell: CellContext<TData>, event: React.MouseEvent) => void;
}

/**
 * TableRegularRows Component
 * 
 * Renders table rows without virtual scrolling.
 * Handles:
 * - Regular row rendering
 * - Cell editing
 * - Row selection
 * - Fixed columns
 */
export const TableRegularRows = React.memo(<TData extends RowData>({
  rows,
  editable,
  editingCell,
  setEditingCell,
  renderCell,
  onRowClick,
  onRowDoubleClick,
  onCellClick,
}: TableRegularRowsProps<TData>) => {
  const handleCellDoubleClick = useCallback((cell: any, row: Row<TData>, columnDef: TableColumn<TData>) => {
    if (editable && columnDef.editable) {
      setEditingCell({
        rowIndex: row.index,
        columnId: cell.column.id,
      });
    }
  }, [editable, setEditingCell]);

  return (
    <>
      {rows.map((row) => (
        <tr
          key={row.id}
          className={[
            'table-tr',
            row.getIsSelected() && 'table-tr--selected',
          ].filter(Boolean).join(' ')}
          onClick={(e) => onRowClick?.(row.original, e)}
          onDoubleClick={(e) => onRowDoubleClick?.(row.original, e)}
        >
          {row.getVisibleCells().map((cell: any) => {
            const columnDef = cell.column.columnDef as TableColumn<TData>;
            const isPinnedLeft = cell.column.getIsPinned() === 'left';
            const isPinnedRight = cell.column.getIsPinned() === 'right';
            const isPinned = isPinnedLeft || isPinnedRight;

            return (
              <td
                key={cell.id}
                className={[
                  'table-td',
                  columnDef.align && `table-td--${columnDef.align}`,
                  isPinned && 'table-td--pinned',
                  isPinnedLeft && 'table-td--pinned-left',
                  isPinnedRight && 'table-td--pinned-right',
                ].filter(Boolean).join(' ')}
                style={{
                  width: cell.column.getSize(),
                  left: isPinnedLeft ? cell.column.getStart() : undefined,
                  right: isPinnedRight ? cell.column.getTotalRight() : undefined,
                }}
                onClick={(e) => onCellClick?.(cell, e)}
                onDoubleClick={() => handleCellDoubleClick(cell, row, columnDef)}
              >
                {renderCell(cell, row.index)}
              </td>
            );
          })}
        </tr>
      ))}
    </>
  );
}) as <TData extends RowData>(props: TableRegularRowsProps<TData>) => React.JSX.Element;

TableRegularRows.displayName = 'TableRegularRows';

import React from 'react';

import { TableRowProps, RowData } from './Table.types';

/**
 * TableRow Component
 * 
 * Renders a single table row with support for:
 * - Selection
 * - Click events
 * - Double-click events
 * - Virtual scrolling
 * - Fixed columns
 */
export const TableRow = React.memo(<TData extends RowData>({
  className = '',
  children,
  onClick,
  onDoubleClick,
  selected = false,
  virtual = false,
  dataIndex,
}: TableRowProps<TData>) => {
  const rowClasses = [
    'table-tr',
    virtual && 'table-tr--virtual',
    selected && 'table-tr--selected',
    className,
  ].filter(Boolean).join(' ');

  return (
    <tr
      className={rowClasses}
      onClick={onClick}
      onDoubleClick={onDoubleClick}
      data-index={dataIndex}
    >
      {children}
    </tr>
  );
}) as <TData extends RowData>(props: TableRowProps<TData>) => React.JSX.Element;

export const TableSort = React.memo(({
  direction,
  onSort,
}: TableSortProps) => {
  const handleClick = () => {
    if (direction === 'asc') {
      onSort('desc');
    } else if (direction === 'desc') {
      onSort('asc');
    } else {
      onSort('asc');
    }
  };

  const getSortIcon = () => {
    if (direction === 'asc') return '↑';
    if (direction === 'desc') return '↓';
    return '↕';
  };

  return (
    <button
      className="table-sort-button"
      onClick={handleClick}
      aria-label={`Sort ${direction || 'unsorted'}`}
    >
      <span className="table-sort-icon">{getSortIcon()}</span>
    </button>
  );
}) as (props: TableSortProps) => React.JSX.Element;

import { flexRender , Row, RowData } from '@tanstack/react-table';
import React, { useCallback } from 'react';

import { TableColumn, CellContext } from './Table.types';

interface TableVirtualizedRowsProps<TData extends RowData> {
  rows: Row<TData>[];
  virtualRows: any[];
  totalSize: number;
  rowVirtualizer: any;
  dynamicRowHeight: boolean;
  editable: boolean;
  editingCell: { rowIndex: number; columnId: string } | null;
  setEditingCell: React.Dispatch<React.SetStateAction<{ rowIndex: number; columnId: string } | null>>;
  renderCell: (cell: any, rowIndex: number) => React.ReactNode;
  onRowClick?: (row: TData, event: React.MouseEvent) => void;
  onRowDoubleClick?: (row: TData, event: React.MouseEvent) => void;
  onCellClick?: (cell: CellContext<TData>, event: React.MouseEvent) => void;
  onCellEdit?: (row: TData, columnId: string, value: unknown) => void;
}

/**
 * TableVirtualizedRows Component
 * 
 * Renders table rows using virtual scrolling for optimal performance
 * with large datasets. Handles:
 * - Virtualized row rendering
 * - Dynamic row height measurement
 * - Cell editing
 * - Row selection
 * - Fixed columns
 */
export const TableVirtualizedRows = React.memo(<TData extends RowData>({
  rows,
  virtualRows,
  totalSize,
  rowVirtualizer,
  dynamicRowHeight,
  editable,
  editingCell,
  setEditingCell,
  renderCell,
  onRowClick,
  onRowDoubleClick,
  onCellClick,
  onCellEdit,
}: TableVirtualizedRowsProps<TData>) => {
  const handleCellDoubleClick = useCallback((cell: any, virtualRow: any, columnDef: TableColumn<TData>) => {
    if (editable && columnDef.editable) {
      setEditingCell({
        rowIndex: virtualRow.index,
        columnId: cell.column.id,
      });
    }
  }, [editable, setEditingCell]);

  return (
    <>
      {/* Spacer for virtualized rows above viewport */}
      {virtualRows.length > 0 && virtualRows[0].start > 0 && (
        <tr style={{ height: virtualRows[0].start }} />
      )}
      {virtualRows.map((virtualRow, index) => {
        const row = rows[virtualRow.index];
        return (
          <tr
            key={row.id}
            data-index={virtualRow.index}
            data-virtualizer={index === 0 ? "true" : undefined}
            ref={dynamicRowHeight ? rowVirtualizer.measureElement : undefined}
            className={[
              'table-tr',
              'table-tr--virtual',
              row.getIsSelected() && 'table-tr--selected',
            ].filter(Boolean).join(' ')}
            onClick={(e) => onRowClick?.(row.original, e)}
            onDoubleClick={(e) => onRowDoubleClick?.(row.original, e)}
          >
            {row.getVisibleCells().map((cell: any) => {
              const columnDef = cell.column.columnDef as TableColumn<TData>;
              const isPinnedLeft = cell.column.getIsPinned() === 'left';
              const isPinnedRight = cell.column.getIsPinned() === 'right';
              const isPinned = isPinnedLeft || isPinnedRight;

              return (
                <td
                  key={cell.id}
                  className={[
                    'table-td',
                    columnDef.align && `table-td--${columnDef.align}`,
                    isPinned && 'table-td--pinned',
                    isPinnedLeft && 'table-td--pinned-left',
                    isPinnedRight && 'table-td--pinned-right',
                  ].filter(Boolean).join(' ')}
                  style={{
                    width: cell.column.getSize(),
                    left: isPinnedLeft ? cell.column.getStart() : undefined,
                    right: isPinnedRight ? cell.column.getTotalRight() : undefined,
                  }}
                  onClick={(e) => onCellClick?.(cell, e)}
                  onDoubleClick={() => handleCellDoubleClick(cell, virtualRow, columnDef)}
                >
                  {renderCell(cell, virtualRow.index)}
                </td>
              );
            })}
          </tr>
        );
      })}
      {/* Spacer for virtualized rows below viewport */}
      {virtualRows.length > 0 && (
        <tr style={{ height: totalSize - virtualRows[virtualRows.length - 1].end }} />
      )}
    </>
  );
}) as <TData extends RowData>(props: TableVirtualizedRowsProps<TData>) => React.JSX.Element;

TableVirtualizedRows.displayName = 'TableVirtualizedRows';

import { useVirtualizer } from '@tanstack/react-virtual';
import { useRef, useEffect, useCallback } from 'react';

import type { VirtualScrollMetrics } from './Table.types';

/**
 * Props for useTableVirtualScroll hook
 */
export interface UseTableVirtualScrollProps<TData> {
  /** Enable virtual scrolling */
  virtual: boolean;
  /** Row height */
  rowHeight: number;
  /** Max height */
  maxHeight: number;
  /** Overscan */
  overscan: number;
  /** Dynamic row height */
  dynamicRowHeight: boolean;
  /** Callback for virtual scroll metrics */
  onVirtualScrollMetrics?: (metrics: VirtualScrollMetrics) => void;
  /** Table rows */
  rows: TData[];
}

/**
 * Result of useTableVirtualScroll hook
 */
export interface UseTableVirtualScrollResult {
  /** Container ref */
  tableContainerRef: React.RefObject<HTMLDivElement>;
  /** Virtual rows */
  virtualRows: ReturnType<typeof useVirtualizer>['getVirtualItems'];
  /** Total size */
  totalSize: number;
  /** Row virtualizer */
  rowVirtualizer: ReturnType<typeof useVirtualizer>;
}

/**
 * Hook for table virtual scrolling
 */
export function useTableVirtualScroll<TData>({
  virtual,
  rowHeight,
  maxHeight,
  overscan,
  dynamicRowHeight,
  onVirtualScrollMetrics,
  rows,
}: UseTableVirtualScrollProps<TData>): UseTableVirtualScrollResult {
  const tableContainerRef = useRef<HTMLDivElement>(null);
  const renderStartTimeRef = useRef<number>(0);

  const rowVirtualizer = useVirtualizer({
    count: rows.length,
    getScrollElement: () => tableContainerRef.current,
    estimateSize: useCallback(
      (index: number) => {
        // Support dynamic row height estimation based on content
        if (dynamicRowHeight) {
          const row = rows[index];
          if (row) {
            // Estimate based on content length (basic heuristic)
            const cellCount = Object.keys(row).length;
            return Math.max(rowHeight, Math.min(rowHeight * 2, cellCount * 20));
          }
        }
        return rowHeight;
      },
      [dynamicRowHeight, rows, rowHeight]
    ),
    overscan,
    measureElement: dynamicRowHeight
      ? (element) => element?.getBoundingClientRect().height
      : undefined,
  });

  const virtualRows = virtual ? rowVirtualizer.getVirtualItems() : [];
  const totalSize = virtual ? rowVirtualizer.getTotalSize() : 0;

  // Report virtual scroll metrics
  useEffect(() => {
    if (virtual && onVirtualScrollMetrics) {
      const metrics: VirtualScrollMetrics = {
        totalRows: rows.length,
        visibleRows: virtualRows.length,
        scrollOffset: rowVirtualizer.scrollOffset ?? 0,
        estimatedRowHeight: rowHeight,
        renderTime: renderStartTimeRef.current > 0 
          ? performance.now() - renderStartTimeRef.current 
          : undefined,
      };
      onVirtualScrollMetrics(metrics);
    }
  }, [virtual, onVirtualScrollMetrics, rows.length, virtualRows.length, rowVirtualizer.scrollOffset, rowHeight]);

  // Track render start time for performance measurement
  useEffect(() => {
    if (virtual) {
      renderStartTimeRef.current = performance.now();
    }
  }, [virtual, virtualRows]);

  return {
    tableContainerRef,
    virtualRows,
    totalSize,
    rowVirtualizer,
  };
}

