/**
 * Hive SQL Linter
 *
 * Provides SQL syntax validation and error detection for Hive SQL.
 * Integrates with CodeMirror's lint extension for real-time feedback.
 */

import { Diagnostic } from '@codemirror/lint';

/**
 * SQL keywords for validation
 */
const SQL_KEYWORDS = [
  'SELECT', 'FROM', 'WHERE', 'JOIN', 'LEFT', 'RIGHT', 'INNER', 'OUTER', 'FULL',
  'ON', 'AND', 'OR', 'NOT', 'IN', 'LIKE', 'BETWEEN', 'NULL', 'IS', 'EXISTS',
  'GROUP', 'BY', 'HAVING', 'ORDER', 'ASC', 'DESC', 'LIMIT', 'OFFSET',
  'INSERT', 'UPDATE', 'DELETE', 'INTO', 'VALUES', 'SET',
  'CREATE', 'ALTER', 'DROP', 'TABLE', 'VIEW', 'INDEX', 'DATABASE',
  'UNION', 'ALL', 'DISTINCT', 'AS', 'WITH', 'CASE', 'WHEN', 'THEN', 'ELSE', 'END',
  // Hive-specific
  'LATERAL', 'VIEW', 'EXPLODE', 'POSEXPLODE', 'CLUSTER', 'DISTRIBUTE', 'SORT',
  'OVER', 'PARTITION', 'RANK', 'ROW_NUMBER', 'DENSE_RANK', 'PERCENT_RANK', 'NTILE',
  'LEAD', 'LAG', 'FIRST_VALUE', 'LAST_VALUE', 'ARRAY', 'MAP', 'STRUCT', 'UNIONTYPE'
];

/**
 * Common function patterns for validation
 */
const FUNCTION_PATTERNS = [
  'get_json_object', 'nvl', 'coalesce', 'concat', 'split', 'substr', 'substring',
  'trim', 'upper', 'lower', 'length', 'to_date', 'date_format', 'from_unixtime',
  'unix_timestamp', 'year', 'month', 'day', 'hour', 'minute', 'second',
  'count', 'sum', 'avg', 'min', 'max', 'grouping', 'rollup', 'cube'
];

/**
 * Check for common SQL syntax errors
 */
function validateBasicSyntax(sql: string): Diagnostic[] {
  const diagnostics: Diagnostic[] = [];
  const lines = sql.split('\n');

  lines.forEach((line, lineIndex) => {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('--')) return;

    // Check for unbalanced parentheses
    const openParens = (line.match(/\(/g) || []).length;
    const closeParens = (line.match(/\)/g) || []).length;
    if (openParens !== closeParens) {
      diagnostics.push({
        from: sql.indexOf(line),
        to: sql.indexOf(line) + line.length,
        severity: 'warning',
        message: 'Unbalanced parentheses detected'
      });
    }

    // Check for common syntax errors
    if (trimmed.includes(',,') || trimmed.includes('(,')) {
      diagnostics.push({
        from: sql.indexOf(line),
        to: sql.indexOf(line) + line.length,
        severity: 'error',
        message: 'Syntax error: double comma or comma after opening parenthesis'
      });
    }

    // Check for SELECT without FROM (basic check)
    if (trimmed.toUpperCase().includes('SELECT') && !trimmed.toUpperCase().includes('FROM')) {
      // Ignore if it's a subquery or UNION
      if (!trimmed.toUpperCase().includes('UNION') && !trimmed.includes('(')) {
        diagnostics.push({
          from: sql.indexOf(line),
          to: sql.indexOf(line) + line.length,
          severity: 'warning',
          message: 'SELECT statement should typically include FROM clause'
        });
      }
    }

    // Check for missing quotes in string literals
    const stringMatches = line.match(/'[^']*'/g);
    if (stringMatches) {
      stringMatches.forEach(match => {
        if (match.endsWith("'")) return; // Properly closed
        diagnostics.push({
          from: sql.indexOf(line) + line.indexOf(match),
          to: sql.indexOf(line) + line.indexOf(match) + match.length,
          severity: 'error',
          message: 'Unclosed string literal'
        });
      });
    }
  });

  return diagnostics;
}

/**
 * Validate Hive SQL specific syntax
 */
function validateHiveSyntax(sql: string): Diagnostic[] {
  const diagnostics: Diagnostic[] = [];
  const upperSQL = sql.toUpperCase();

  // Check for LATERAL VIEW without EXPLODE
  if (upperSQL.includes('LATERAL VIEW') && !upperSQL.includes('EXPLODE') && !upperSQL.includes('POSEXPLODE')) {
    diagnostics.push({
      from: 0,
      to: sql.length,
      severity: 'warning',
      message: 'LATERAL VIEW should typically be used with EXPLODE or POSEXPLODE'
    });
  }

  // Check for window functions without OVER
  const windowFunctions = ['RANK', 'ROW_NUMBER', 'DENSE_RANK', 'PERCENT_RANK', 'NTILE', 'LEAD', 'LAG', 'FIRST_VALUE', 'LAST_VALUE'];
  windowFunctions.forEach(func => {
    const regex = new RegExp(`\\b${func}\\s*\\(`, 'gi');
    const matches = sql.match(regex);
    if (matches) {
      matches.forEach(match => {
        const index = sql.toUpperCase().indexOf(match);
        // Check if OVER is nearby
        const context = sql.substring(index, index + 100);
        if (!context.toUpperCase().includes('OVER')) {
          diagnostics.push({
            from: index,
            to: index + match.length,
            severity: 'warning',
            message: `Window function ${func} should be used with OVER clause`
          });
        }
      });
    }
  });

  // Check for CREATE VIEW without OR REPLACE
  if (upperSQL.includes('CREATE VIEW') && !upperSQL.includes('CREATE OR REPLACE VIEW')) {
    diagnostics.push({
      from: 0,
      to: sql.length,
      severity: 'info',
      message: 'Consider using CREATE OR REPLACE VIEW for safer view updates'
    });
  }

  return diagnostics;
}

/**
 * Main linting function for Hive SQL
 *
 * @param sql - SQL string to validate
 * @returns Array of diagnostics (errors, warnings, info)
 */
export function lintHQL(sql: string): Diagnostic[] {
  const diagnostics: Diagnostic[] = [];

  // Skip empty or whitespace-only SQL
  if (!sql || sql.trim().length === 0) {
    return diagnostics;
  }

  // Basic syntax validation
  diagnostics.push(...validateBasicSyntax(sql));

  // Hive-specific validation
  diagnostics.push(...validateHiveSyntax(sql));

  return diagnostics;
}

/**
 * Create a CodeMirror linter extension
 * This function returns a linter that can be used with @codemirror/lint
 */
export function createHiveLinter() {
  return (view: any) => {
    const sql = view.state.doc.toString();
    const diagnostics = lintHQL(sql);
    return diagnostics;
  };
}

/**
 * Quick validation for non-editor use (e.g., before save)
 *
 * @param sql - SQL string to validate
 * @returns Object with validation result and errors
 */
export function validateHQLQuick(sql: string): {
  valid: boolean;
  errors: string[];
  warnings: string[];
} {
  const diagnostics = lintHQL(sql);

  const errors = diagnostics
    .filter(d => d.severity === 'error')
    .map(d => d.message || 'Unknown error');

  const warnings = diagnostics
    .filter(d => d.severity === 'warning')
    .map(d => d.message || 'Unknown warning');

  return {
    valid: errors.length === 0,
    errors,
    warnings
  };
}

/**
 * Performance Monitoring Utility
 *
 * Tracks React component performance metrics:
 * - Render time
 * - Re-render count
 * - Memory usage
 * - FPS (frames per second)
 *
 * Usage:
 * import { usePerformanceMonitor } from '@shared/utils/performanceMonitor';
 *
 * function MyComponent() {
 *   usePerformanceMonitor('MyComponent');
 *   return <div>...</div>;
 * }
 */

import { useEffect, useRef } from 'react';

export interface PerformanceMetrics {
  componentName: string;
  renderCount: number;
  totalRenderTime: number;
  averageRenderTime: number;
  lastRenderTime: number;
  memoryUsage?: number;
}

class PerformanceMonitor {
  private static instance: PerformanceMonitor;
  private metrics: Map<string, PerformanceMetrics> = new Map();
  private observers: PerformanceObserver[] = [];
  private fps: number = 60;
  private lastFrameTime: number = performance.now();

  private constructor() {
    this.setupPerformanceObserver();
    this.startFPSMonitoring();
  }

  static getInstance(): PerformanceMonitor {
    if (!PerformanceMonitor.instance) {
      PerformanceMonitor.instance = new PerformanceMonitor();
    }
    return PerformanceMonitor.instance;
  }

  private setupPerformanceObserver() {
    if (typeof window === 'undefined' || !window.PerformanceObserver) {
      return;
    }

    // Observe render performance
    const renderObserver = new PerformanceObserver((list) => {
      for (const entry of list.getEntries()) {
        if (entry.entryType === 'measure') {
          const componentName = entry.name.replace('render-', '');
          this.updateRenderMetrics(componentName, entry.duration);
        }
      }
    });

    renderObserver.observe({ entryTypes: ['measure'] });
    this.observers.push(renderObserver);
  }

  private startFPSMonitoring() {
    if (typeof window === 'undefined') return;

    const measureFPS = () => {
      const now = performance.now();
      const delta = now - this.lastFrameTime;
      this.fps = 1000 / delta;
      this.lastFrameTime = now;
      requestAnimationFrame(measureFPS);
    };

    requestAnimationFrame(measureFPS);
  }

  private updateRenderMetrics(componentName: string, renderTime: number) {
    const existing = this.metrics.get(componentName);

    if (existing) {
      existing.renderCount++;
      existing.totalRenderTime += renderTime;
      existing.averageRenderTime = existing.totalRenderTime / existing.renderCount;
      existing.lastRenderTime = renderTime;
      existing.memoryUsage = this.getMemoryUsage();
    } else {
      this.metrics.set(componentName, {
        componentName,
        renderCount: 1,
        totalRenderTime: renderTime,
        averageRenderTime: renderTime,
        lastRenderTime: renderTime,
        memoryUsage: this.getMemoryUsage()
      });
    }
  }

  private getMemoryUsage(): number | undefined {
    if (
      typeof window !== 'undefined' &&
      'memory' in performance &&
      (performance as any).memory
    ) {
      return (performance as any).memory.usedJSHeapSize / 1048576; // Convert to MB
    }
    return undefined;
  }

  recordRender(componentName: string) {
    if (typeof window === 'undefined' || !window.performance) {
      return;
    }

    const startTime = performance.now();

    return () => {
      const endTime = performance.now();
      const renderTime = endTime - startTime;

      performance.mark(`render-start-${componentName}`);
      performance.mark(`render-end-${componentName}`);
      performance.measure(
        `render-${componentName}`,
        `render-start-${componentName}`,
        `render-end-${componentName}`
      );

      // Clean up marks
      performance.clearMarks(`render-start-${componentName}`);
      performance.clearMarks(`render-end-${componentName}`);
    };
  }

  getMetrics(componentName?: string): PerformanceMetrics | PerformanceMetrics[] {
    if (componentName) {
      return this.metrics.get(componentName)!;
    }
    return Array.from(this.metrics.values());
  }

  getFPS(): number {
    return this.fps;
  }

  getSystemMemoryUsage(): number | undefined {
    return this.getMemoryUsage();
  }

  reset() {
    this.metrics.clear();
  }

  logMetrics(componentName?: string) {
    const metrics = componentName
      ? [this.getMetrics(componentName) as PerformanceMetrics]
      : (this.getMetrics() as PerformanceMetrics[]);

    console.group('🚀 Performance Metrics');

    metrics.forEach((metric) => {
      console.log(`📊 ${metric.componentName}:`, {
        'Render Count': metric.renderCount,
        'Avg Render Time': `${metric.averageRenderTime.toFixed(2)}ms`,
        'Last Render Time': `${metric.lastRenderTime.toFixed(2)}ms`,
        'Total Render Time': `${metric.totalRenderTime.toFixed(2)}ms`,
        'Memory Usage': metric.memoryUsage
          ? `${metric.memoryUsage.toFixed(2)}MB`
          : 'N/A'
      });
    });

    console.log(`🎯 FPS: ${this.fps.toFixed(1)}`);

    console.groupEnd();
  }

  warnOnSlowRender(componentName: string, threshold: number = 16.67) {
    const metrics = this.metrics.get(componentName);
    if (metrics && metrics.lastRenderTime > threshold) {
      console.warn(
        `⚠️ Slow render detected in ${componentName}: ${metrics.lastRenderTime.toFixed(2)}ms`
      );
    }
  }
}

// React Hook for performance monitoring
export function usePerformanceMonitor(componentName: string, threshold?: number) {
  const monitor = useRef<PerformanceMonitor>(PerformanceMonitor.getInstance());

  useEffect(() => {
    if (typeof window === 'undefined' || !window.performance) {
      return;
    }

    const stopRecording = monitor.current.recordRender(componentName);

    return () => {
      if (threshold) {
        monitor.current.warnOnSlowRender(componentName, threshold);
      }
    };
  }, [componentName, threshold]);
}

// Export singleton instance
export const performanceMonitor = PerformanceMonitor.getInstance();

// Export utility functions
export function logPerformanceMetrics(componentName?: string) {
  performanceMonitor.logMetrics(componentName);
}

export function getPerformanceMetrics(componentName?: string) {
  return performanceMonitor.getMetrics(componentName);
}

export function getFPS() {
  return performanceMonitor.getFPS();
}

export function getMemoryUsage() {
  return performanceMonitor.getSystemMemoryUsage();
}

export function resetPerformanceMetrics() {
  performanceMonitor.reset();
}

